#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int minFlips(string target) {
        int flips = 0, current = 0;
        for (char c : target) {
            int bit = c - '0';
            if (bit != current) { ++flips; current = bit; }
        }
        return flips;
    }
};
